"use client"
import React, { useEffect, useState } from "react"
import axios from "axios"
import { TodoCard } from "@/components/TodoCard"
import UpdateTodoForm from "@/components/UpdateTodoForm"

type Todo = {
  _id: string
  title: string
  description: string
  status: string
  deadline: string
}

export default function Dashboard({ params }: { params: { userId: string } }) {
  const [todos, setTodos] = useState<Todo[]>([])
  const [showUpdateForm, setShowUpdateForm] = useState(false)
  const [selectedTodo, setSelectedTodo] = useState<Todo | null>(null)

  const getTodos = async () => {
    try {
      const res = await axios.get(`/api/users/${params.userId}/todos`)
      setTodos(res.data.todos)
    } catch (error) {
      console.error("Error fetching todos:", error)
    }
  }

  const handleEditClick = (todo: Todo) => {
    setSelectedTodo(todo)
    setShowUpdateForm(true)
  }

  const handleUpdateComplete = () => {
    setShowUpdateForm(false)
    setSelectedTodo(null)
    getTodos()
  }

  useEffect(() => {
    getTodos()
  }, [])

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <h1 className="text-3xl font-bold mb-6">Your Todos</h1>

      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {todos.map((todo) => (
          <TodoCard key={todo._id} todo={todo} onEdit={() => handleEditClick(todo)} />
        ))}
      </div>

      {showUpdateForm && selectedTodo && (
        <div className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50">
          <UpdateTodoForm
            todo={selectedTodo}
            userId={params.userId}
            onClose={() => setShowUpdateForm(false)}
            onTodoUpdated={handleUpdateComplete}
          />
        </div>
      )}
    </div>
  )
}
